import pathlib,json,uuid,shutil
R=pathlib.Path(__file__).resolve().parents[1]
def write(p,d):
 p=R/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def uid(s):return str(uuid.uuid5(uuid.NAMESPACE_URL,'https://shiratama984-lab/rpg/v1/'+s))
write('behavior_pack/manifest.json',{'format_version':2,'header':{'name':'冒険と王国 RPG 0.1.0','description':'剣・魔法・依頼・経済・建国 / 非公式オリジナル試作版','uuid':uid('bp'),'version':[0,1,0],'min_engine_version':[1,21,80]},'modules':[{'type':'data','uuid':uid('data'),'version':[0,1,0]},{'type':'script','language':'javascript','entry':'scripts/main.js','uuid':uid('script'),'version':[0,1,0]}],'dependencies':[{'module_name':'@minecraft/server','version':'2.0.0'},{'module_name':'@minecraft/server-ui','version':'2.0.0'},{'uuid':uid('rp'),'version':[0,1,0]}]})
write('resource_pack/manifest.json',{'format_version':2,'header':{'name':'冒険と王国 RPG — 画像とUI','description':'独自の羊皮紙メニュー・ピクセルアイコン・魔物','uuid':uid('rp'),'version':[0,1,0],'min_engine_version':[1,21,80]},'modules':[{'type':'resources','uuid':uid('resources'),'version':[0,1,0]}],'subpacks':[{'folder_name':'illustrated','name':'画像UI（冒険者手帳・市場）','memory_tier':0},{'folder_name':'standard','name':'標準UI（互換モード）','memory_tier':1}]})
shutil.copyfile(R/'resource_pack/pack_icon.png',R/'behavior_pack/pack_icon.png')
for id,name,texture in [('adventure_book','§6冒険者手帳','book'),('oak_staff','§b樫の杖','staff'),('adventurer_blade','§f冒険者の剣','sword')]:
 c={'minecraft:display_name':{'value':name},'minecraft:icon':'arpg_'+texture,'minecraft:max_stack_size':1}
 if id=='adventurer_blade':c.update({'minecraft:damage':7,'minecraft:durability':{'max_durability':384},'minecraft:enchantable':{'slot':'sword','value':8},'minecraft:hand_equipped':True})
 else:c.update({'minecraft:interact_button':'手帳を開く' if id=='adventure_book' else '魔法を発動','minecraft:use_modifiers':{'use_duration':0.1,'movement_modifier':1},'minecraft:use_animation':'bow'})
 write('behavior_pack/items/'+id+'.json',{'format_version':'1.21.80','minecraft:item':{'description':{'identifier':'arpg:'+id,'menu_category':{'category':'equipment'}},'components':c}})
write('resource_pack/textures/item_texture.json',{'resource_pack_name':'adventure_realm','texture_name':'atlas.items','texture_data':{'arpg_'+k:{'textures':'textures/arpg/'+k} for k in ['book','staff','sword']}})
for name,ingredients in [('adventure_book',[{'item':'minecraft:book'},{'item':'minecraft:emerald'}]),('oak_staff',[{'item':'minecraft:stick','count':2},{'item':'minecraft:amethyst_shard'}]),('adventurer_blade',[{'item':'minecraft:iron_ingot','count':3},{'item':'minecraft:stick'}])]:
 write('behavior_pack/recipes/'+name+'.json',{'format_version':'1.20.10','minecraft:recipe_shapeless':{'description':{'identifier':'arpg:recipe_'+name},'tags':['crafting_table'],'ingredients':ingredients,'result':{'item':'arpg:'+name,'count':1}}})
# This humanoid mesh was authored for this project; no reference model or skin is used.
mesh={'format_version': '1.12.0', 'minecraft:geometry': [{'description': {'identifier': 'geometry.arpg.humanoid', 'texture_width': 64, 'texture_height': 32, 'visible_bounds_width': 2, 'visible_bounds_height': 3, 'visible_bounds_offset': [0, 1.5, 0]}, 'bones': [{'name': 'body', 'pivot': [0, 24, 0], 'cubes': [{'origin': [-4, 12, -2], 'size': [8, 12, 4], 'uv': [16, 16]}]}, {'name': 'head', 'pivot': [0, 24, 0], 'cubes': [{'origin': [-4, 24, -4], 'size': [8, 8, 8], 'uv': [0, 0]}, {'origin': [-4, 24, -4], 'size': [8, 8, 8], 'uv': [32, 0], 'inflate': 0.5}]}, {'name': 'rightArm', 'pivot': [-5, 22, 0], 'cubes': [{'origin': [-8, 12, -2], 'size': [4, 12, 4], 'uv': [40, 16]}]}, {'name': 'leftArm', 'pivot': [5, 22, 0], 'mirror': True, 'cubes': [{'origin': [4, 12, -2], 'size': [4, 12, 4], 'uv': [40, 16]}]}, {'name': 'rightLeg', 'pivot': [-2, 12, 0], 'cubes': [{'origin': [-4, 0, -2], 'size': [4, 12, 4], 'uv': [0, 16]}]}, {'name': 'leftLeg', 'pivot': [2, 12, 0], 'mirror': True, 'cubes': [{'origin': [0, 0, -2], 'size': [4, 12, 4], 'uv': [0, 16]}]}]}]}
write('resource_pack/models/entity/humanoid.geo.json',mesh)
write('resource_pack/animations/humanoid.animation.json',{'format_version':'1.8.0','animations':{'animation.arpg.walk':{'loop':True,'bones':{b:{'rotation':[f'math.cos(query.modified_distance_moved * 38.17) * {a} * query.modified_move_speed',0,0]} for b,a in [('rightArm',-65),('leftArm',65),('rightLeg',65),('leftLeg',-65)]}}}})
write('resource_pack/render_controllers/humanoid.json',{'format_version':'1.8.0','render_controllers':{'controller.render.arpg':{'geometry':'Geometry.default','materials':[{'*':'Material.default'}],'textures':['Texture.default']}}})
for name,label,hp,dmg in [('raider','野盗',24,4),('shade','影の魔物',18,3)]:
 write('behavior_pack/entities/'+name+'.json',{'format_version':'1.21.80','minecraft:entity':{'description':{'identifier':'arpg:'+name,'is_spawnable':True,'is_summonable':True,'is_experimental':False},'component_groups':{'arpg:persistent':{'minecraft:persistent':{}}},'events':{'arpg:raid':{'add':{'component_groups':['arpg:persistent']}}},'components':{'minecraft:type_family':{'family':['arpg_enemy','monster','mob']},'minecraft:health':{'value':hp,'max':hp},'minecraft:attack':{'damage':dmg},'minecraft:collision_box':{'width':0.6,'height':1.8},'minecraft:physics':{},'minecraft:movement':{'value':0.23},'minecraft:movement.basic':{},'minecraft:navigation.walk':{'can_path_over_water':False,'avoid_water':True},'minecraft:jump.static':{},'minecraft:despawn':{'despawn_from_distance':{}},'minecraft:breathable':{'total_supply':15,'suffocate_time':0},'minecraft:pushable':{'is_pushable':True,'is_pushable_by_piston':True},'minecraft:nameable':{},'minecraft:loot':{'table':'loot_tables/entities/'+name+'.json'},'minecraft:experience_reward':{'on_death':'query.last_hit_by_player ? 3 : 0'},'minecraft:behavior.float':{'priority':0},'minecraft:behavior.hurt_by_target':{'priority':1},'minecraft:behavior.nearest_attackable_target':{'priority':2,'must_see':True,'reselect_targets':True,'entity_types':[{'filters':{'test':'is_family','subject':'other','value':'player'},'max_dist':24}]},'minecraft:behavior.melee_attack':{'priority':3,'speed_multiplier':1.1,'track_target':True},'minecraft:behavior.random_stroll':{'priority':6,'speed_multiplier':0.6},'minecraft:behavior.look_at_player':{'priority':7,'look_distance':8}}}})
 write('behavior_pack/loot_tables/entities/'+name+'.json',{'pools':[{'rolls':1,'entries':[{'type':'item','name':'minecraft:iron_nugget','weight':1,'functions':[{'function':'set_count','count':{'min':1,'max':3}}]}]}]})
 write('behavior_pack/spawn_rules/'+name+'.json',{'format_version':'1.8.0','minecraft:spawn_rules':{'description':{'identifier':'arpg:'+name,'population_control':'monster'},'conditions':[{'minecraft:spawns_on_surface':{},'minecraft:brightness_filter':{'min':0,'max':7,'adjust_for_weather':True},'minecraft:difficulty_filter':{'min':'easy','max':'hard'},'minecraft:weight':{'default':3},'minecraft:herd':{'min_size':1,'max_size':1},'minecraft:density_limit':{'surface':2,'underground':0},'minecraft:biome_filter':{'test':'has_biome_tag','operator':'==','value':'overworld'}}]}})
 write('resource_pack/entity/'+name+'.entity.json',{'format_version':'1.10.0','minecraft:client_entity':{'description':{'identifier':'arpg:'+name,'materials':{'default':'entity_alphatest'},'textures':{'default':'textures/entity/'+name},'geometry':{'default':'geometry.arpg.humanoid'},'animations':{'walk':'animation.arpg.walk','look':'animation.common.look_at_target'},'scripts':{'animate':['walk','look']},'render_controllers':['controller.render.arpg'],'spawn_egg':{'base_color':'#645142' if name=='raider' else '#393a63','overlay_color':'#dcae53'}}}})
text=R/'resource_pack/texts';text.mkdir(exist_ok=True);write('resource_pack/texts/languages.json',['ja_JP','en_US'])
for lang in ['ja_JP','en_US']:(text/(lang+'.lang')).write_text('entity.arpg:raider.name=野盗\nentity.arpg:shade.name=影の魔物\n')
HOME='§6冒険者手帳 §0[ARPG:HOME]';SHOP='§6城下町の市場 §0[ARPG:MARKET]'
def visible(expr):return [{'binding_name':'#title_text'},{'binding_type':'view','source_property_name':expr,'target_property_name':'#visible'}]
controls=[]
for key,title,child,size,condition in [('normal','#title_text','server_form.long_form_panel',[225,200],f"((not (#title_text = '{HOME}')) and (not (#title_text = '{SHOP}')))"),('journal','冒険者手帳','arpg_forms.home_content',[304,240],f"(#title_text = '{HOME}')"),('market','城下町の市場','arpg_forms.market_content',[304,240],f"(#title_text = '{SHOP}')")]:
 controls.append({key+'@common_dialogs.main_panel_no_buttons':{'$title_panel':'common_dialogs.standard_title_label','$title_size':['100% - 14px',10],'$text_name':title,'$title_text_binding_type':'none','$child_control':child,'size':size,'layer':2,'bindings':visible(condition)}})
write('resource_pack/ui/server_form.json',{'namespace':'server_form','long_form':{'type':'panel','size':['100%','100%'],'controls':controls}})
forms={'namespace':'arpg_forms'}
for name,rows,cell_h in [('home',2,78),('market',3,52)]:
 forms[name+'_content']={'type':'panel','size':['100%','100%'],'controls':[{'paper':{'type':'image','texture':'textures/arpg/parchment','size':['100%','100%'],'layer':0}}, {'summary':{'type':'label','text':'#form_text','color':[0.2,0.15,0.1],'font_scale_factor':0.8,'size':['100% - 32px',30],'anchor_from':'top_middle','anchor_to':'top_middle','offset':[0,12],'layer':3,'text_alignment':'center','bindings':[{'binding_name':'#form_text'}]}},{'grid':{'type':'grid','size':[264,rows*cell_h],'anchor_from':'top_middle','anchor_to':'top_middle','offset':[0,45],'grid_dimensions':[3,rows],'grid_item_template':'arpg_forms.'+name+'_button','grid_fill_direction':'horizontal','collection_name':'form_buttons','bindings':[{'binding_name':'#form_button_length','binding_name_override':'#maximum_grid_items'}]}}]}
 forms[name+'_button']={'type':'panel','size':[88,cell_h],'controls':[{'select@common_buttons.light_text_button':{'size':[84,cell_h-4],'anchor_from':'center','anchor_to':'center','$button_text':'','$button_text_binding_type':'none','$pressed_button_name':'button.form_button_click','layer':1,'bindings':[{'binding_type':'collection_details','binding_collection_name':'form_buttons'}]}},{'icon':{'type':'image','size':[32,32] if name=='home' else [24,24],'anchor_from':'top_middle','anchor_to':'top_middle','offset':[0,5],'layer':3,'bindings':[{'binding_name':'#form_button_texture','binding_name_override':'#texture','binding_type':'collection','binding_collection_name':'form_buttons'},{'binding_name':'#form_button_texture_file_system','binding_name_override':'#texture_file_system','binding_type':'collection','binding_collection_name':'form_buttons'}]}},{'caption':{'type':'label','text':'#form_button_text','size':[80,24] if name=='home' else [82,18],'anchor_from':'bottom_middle','anchor_to':'bottom_middle','offset':[0,-5],'font_scale_factor':0.8 if name=='home' else 0.65,'color':[0.16,0.13,0.1],'text_alignment':'center','layer':4,'bindings':[{'binding_name':'#form_button_text','binding_type':'collection','binding_collection_name':'form_buttons'}]}}]}
write('resource_pack/ui/arpg_forms.json',forms)
write('resource_pack/ui/_ui_defs.json',{'ui_defs':['ui/arpg_forms.json']})
print('Generated standalone RPG packs, recipes, monsters and scoped image UI')

write('resource_pack/subpacks/standard/ui/server_form.json',{'namespace':'server_form','long_form':{'type':'panel','size':['100%','100%'],'controls':[controls[0]]}})
# The compatibility mode must show the native form for *all* titles.
p=R/'resource_pack/subpacks/standard/ui/server_form.json'
d=json.loads(p.read_text());d['long_form']['controls'][0]['normal@common_dialogs.main_panel_no_buttons'].pop('bindings');p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
(R/'resource_pack/subpacks/illustrated').mkdir(parents=True,exist_ok=True)
(R/'resource_pack/subpacks/illustrated/README.txt').write_text('Image UI uses the main resource-pack UI definitions.\n')
